package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem string // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct int64 // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsDiscount decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string // PIC ZZ,ZZ9.99 len=9
var WsNetEd string // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec

var inputLines []string
var inputIdx int
var inputOpen bool

func pow10(n int) decimal.Decimal {
	r := decimal.NewFromInt(1)
	for i := 0; i < n; i++ {
		r = r.Mul(decimal.NewFromInt(10))
	}
	return r
}

func fitRound(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	d = d.Round(int32(scale))
	modBase := pow10(intDigits + scale)
	scaled := d.Shift(int32(scale))
	// keep low-order digits; assume non-negative (all values here are >=0)
	// handle sign preserving: work on absolute then reapply
	neg := scaled.IsNegative()
	if neg {
		scaled = scaled.Abs()
	}
	scaled = scaled.Mod(modBase)
	if neg {
		scaled = scaled.Neg()
	}
	return scaled.Shift(int32(-scale))
}

func fitTruncate(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	d = d.Truncate(int32(scale))
	modBase := pow10(intDigits + scale)
	scaled := d.Shift(int32(scale))
	neg := scaled.IsNegative()
	if neg {
		scaled = scaled.Abs()
	}
	scaled = scaled.Mod(modBase)
	if neg {
		scaled = scaled.Neg()
	}
	return scaled.Shift(int32(-scale))
}

func parseDigits(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return v
}

func formatEdited(val decimal.Decimal, picture string) string {
	// split picture at '.'
	dot := strings.Index(picture, ".")
	var intPic, fracPic string
	if dot >= 0 {
		intPic = picture[:dot]
		fracPic = picture[dot+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	// count digit slots
	nInt := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			nInt++
		}
	}
	nFrac := 0
	for i := 0; i < len(fracPic); i++ {
		if fracPic[i] == 'Z' || fracPic[i] == '9' {
			nFrac++
		}
	}
	neg := val.IsNegative()
	absVal := val.Abs()
	// truncate to frac scale (values already fit; MOVE truncates)
	absVal = absVal.Truncate(int32(nFrac))
	totalScaled := int64(0)
	if nFrac > 0 {
		totalScaled = absVal.Shift(int32(nFrac)).Truncate(0).IntPart()
	} else {
		totalScaled = absVal.Truncate(0).IntPart()
	}
	if totalScaled < 0 {
		totalScaled = -totalScaled
	}
	// drop high-order integer digits
	modBase := int64(1)
	for i := 0; i < nInt+nFrac; i++ {
		modBase *= 10
	}
	if modBase != 0 {
		totalScaled = totalScaled % modBase
	}
	powF := int64(1)
	for i := 0; i < nFrac; i++ {
		powF *= 10
	}
	var intPart, fracPart int64
	if nFrac > 0 {
		intPart = totalScaled / powF
		fracPart = totalScaled % powF
	} else {
		intPart = totalScaled
		fracPart = 0
	}
	intDigits := make([]int, nInt)
	tmp := intPart
	for i := nInt - 1; i >= 0; i-- {
		intDigits[i] = int(tmp % 10)
		tmp /= 10
	}
	fracDigits := make([]int, nFrac)
	tmp = fracPart
	for i := nFrac - 1; i >= 0; i-- {
		fracDigits[i] = int(tmp % 10)
		tmp /= 10
	}
	var b strings.Builder
	suppressing := true
	// check if all int digits are zero: still suppress Zs
	digitIdx := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		switch c {
		case 'Z':
			d := intDigits[digitIdx]
			digitIdx++
			// look ahead: is there any non-zero digit remaining (including this)?
			// suppressing means all previous digits were zero
			if suppressing && d == 0 {
				// need to know if any later digit non-zero; if so still suppress this one
				// if all remaining are zero, also suppress
				b.WriteByte(' ')
			} else {
				b.WriteByte(byte('0' + d))
				suppressing = false
			}
			// if d != 0, suppressing becomes false; handled above
			// if d==0 but suppressing was already false, we printed 0 and stay false
			if d != 0 {
				suppressing = false
			} else {
				if !suppressing {
					// already false, keep false (we printed 0)
				}
			}
		case '9':
			d := intDigits[digitIdx]
			digitIdx++
			b.WriteByte(byte('0' + d))
			suppressing = false
		case ',':
			if suppressing {
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		default:
			b.WriteByte(c)
		}
	}
	if dot >= 0 {
		b.WriteByte('.')
		fIdx := 0
		for i := 0; i < len(fracPic); i++ {
			c := fracPic[i]
			if c == 'Z' || c == '9' {
				b.WriteByte(byte('0' + fracDigits[fIdx]))
				fIdx++
			} else {
				b.WriteByte(c)
			}
		}
	}
	s := b.String()
	_ = neg
	return s
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func MainPara() {
	WsEofFlag = "N"
	WsDiscount = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalNet = decimal.NewFromInt(0)
	WsCount = 0
	// OPEN INPUT DISC-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		inputLines = nil
		inputIdx = 0
		inputOpen = false
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		var lines []string
		for sc.Scan() {
			t := sc.Text()
			// strip trailing \r if present (CRLF)
			if len(t) > 0 && t[len(t)-1] == '\r' {
				t = t[:len(t)-1]
			}
			lines = append(lines, t)
		}
		f.Close()
		inputLines = lines
		inputIdx = 0
		inputOpen = true
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE DISC-FILE
	inputOpen = false
	SummaryPara()
}

func ReadPara() {
	if !inputOpen || inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse 01 DISC-REC
	sItem := line[0:6]
	sPrice := line[6:13]
	sPct := line[13:15]
	discRec.DrItem = sItem
	nPrice := parseDigits(sPrice)
	discRec.DrPrice = decimal.New(nPrice, -2)
	discRec.DrPct = parseDigits(sPct)
	// normalize pct to 0-99 low-order? file should already fit; keep modulo 100
	discRec.DrPct = discRec.DrPct % 100
}

func ProcessPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	raw := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	WsDiscount = fitRound(raw, 5, 2)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	WsNet = fitTruncate(discRec.DrPrice.Sub(WsDiscount), 5, 2)
	// ADD WS-NET TO WS-TOTAL-NET
	WsTotalNet = fitTruncate(WsTotalNet.Add(WsNet), 8, 2)
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 1000
	// MOVE ...
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	_ = padRight
	MainPara()
}
